#ifndef IME_H
#define IME_H

/*
 * ime.h -- minimal pinyin IME over the US-QWERTY keyboard.
 *
 * F2 toggles it.  While active, letter keys build a pinyin syllable and
 * a candidate bar appears on the bottom console row (saved and restored
 * verbatim by the display front-end, so it never destroys output).
 * Digits 1..9 pick a candidate, Space picks the first, -/= page, Esc
 * cancels, Backspace edits the syllable.
 *
 * Data: src/pinyin.inc (generated by tools/gen_pinyin.py from pypinyin
 * + jieba frequency, committed, no build-time dependency).
 */
#define IME_PASS     0     /* key not consumed -- caller handles it */
#define IME_CONSUME  1     /* key consumed, nothing committed       */
#define IME_COMMIT   2     /* *out holds UTF-8 hanzi + NUL          */

int  ime_active(void);
int  ime_feed(int key, char out[5]);   /* returns IME_PASS / CONSUME / COMMIT */
void ime_refresh(void);                /* repaint the bar after a redraw */
void ime_off(void);                    /* force-close bar + deactivate   */

#endif
